#!/usr/bin/env node
/**
 * Regenerate the optional `@yankeguo/dsh-disable-goal-bundle` patch from the
 * DSH copy installed on this machine.
 *
 * The companion bundle turns the built-in dsh-goal mode off as a normal bundle
 * layer: install/enable it from the Plugins UI (or `dsh plugin add`) and the
 * profile's cordis.patch.yml stays clean; disable it to restore the built-in
 * goal mode. Its patch is a snapshot of the shipped preset child lists, so it
 * must be regenerated after a DSH upgrade:
 *
 *   node scripts/build-disable-goal-bundle.mjs            # rewrite the patch
 *   node scripts/build-disable-goal-bundle.mjs --check    # fail when stale
 *   node scripts/build-disable-goal-bundle.mjs --print    # print the patch
 *   node scripts/build-disable-goal-bundle.mjs --app-asar <path> --presets-dir <dir>
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import {
  DEFAULT_ASAR,
  buildDisableGoalEntries,
  loadPresetPatches,
  readDshVersion,
} from './lib/disable-goal.mjs'

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const DEFAULT_OUT = join(ROOT, 'packages', 'disable-goal-bundle', 'cordis.patch.yml')

const USAGE = `Usage:
  node scripts/build-disable-goal-bundle.mjs [--print] [--check]
  Options:
    --print                print the generated patch instead of writing it
    --check                exit 1 when packages/disable-goal-bundle/cordis.patch.yml is stale
    --out <path>           output file (default packages/disable-goal-bundle/cordis.patch.yml)
    --app-asar <path>      installed app.asar (default ${DEFAULT_ASAR})
    --presets-dir <path>   read preset patches from a directory instead of app.asar
    --exclude <names>      comma-separated preset names to skip
`

/** Parse arguments. */
function parseArgs(argv) {
  const options = { mode: 'write', out: DEFAULT_OUT, appAsar: DEFAULT_ASAR, presetsDir: undefined, exclude: [] }
  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index]
    switch (arg) {
      case '--print':
        options.mode = 'print'
        break
      case '--check':
        options.mode = 'check'
        break
      case '--out':
        options.out = resolve(argv[++index])
        break
      case '--app-asar':
        options.appAsar = resolve(argv[++index])
        break
      case '--presets-dir':
        options.presetsDir = resolve(argv[++index])
        break
      case '--exclude':
        options.exclude = argv[++index].split(',').map(name => name.trim()).filter(Boolean)
        break
      case '-h':
      case '--help':
        process.stdout.write(USAGE)
        process.exit(0)
      // fallthrough for unknown flags
      default:
        throw new Error(`unknown argument: ${arg}`)
    }
  }
  return options
}

/** Render the full bundle patch text. */
function renderPatch(options) {
  const presetPatches = loadPresetPatches(options)
  if (presetPatches.size === 0) throw new Error('all presets were excluded; nothing to generate')
  const version = options.presetsDir === undefined ? readDshVersion(options.appAsar) : 'unknown'
  return [
    '# GENERATED by scripts/build-disable-goal-bundle.mjs — do not edit by hand.',
    '#',
    '# Companion bundle for @yankeguo/dsh-infini-goal: disables the built-in',
    '# dsh-goal mode as an ordinary bundle layer, so a profile patch stays clean.',
    '# Install/enable it to disable; disable it to restore the built-in mode.',
    '#',
    '# The shipped Web composition keeps the `goal` SERVICE on the host plane but',
    '# mounts command-goal/tool-goal per agent preset; removing the service makes',
    '# preset activation fail with "waiting for goals". This layer therefore only',
    '# disables the automatic-round driver and the client GoalBar, and replaces',
    '# the shipped preset child lists with the same lists minus those two rows.',
    '#',
    `# Generated against DSH runtime ${version}. Regenerate after a DSH upgrade:`,
    '#   node scripts/build-disable-goal-bundle.mjs',
    ...buildDisableGoalEntries(presetPatches),
    '',
  ].join('\n')
}

try {
  const options = parseArgs(process.argv.slice(2))
  const patch = renderPatch(options)
  if (options.mode === 'print') {
    process.stdout.write(patch)
  } else if (options.mode === 'check') {
    let current = ''
    try {
      current = readFileSync(options.out, 'utf8')
    } catch {
      current = ''
    }
    if (current !== patch) {
      console.error(`build-disable-goal-bundle: ${options.out} is stale; run without --check to regenerate`)
      process.exit(1)
    }
    console.log(`build-disable-goal-bundle: ${options.out} is up to date`)
  } else {
    writeFileSync(options.out, patch)
    console.log(`wrote ${options.out}`)
  }
} catch (error) {
  console.error(`build-disable-goal-bundle: ${error instanceof Error ? error.message : String(error)}`)
  process.exit(1)
}
